<?php $s = $edit ?? []; ?>
<div class="page-head"><div><div class="breadcrumb"><a href="<?= e(url('/services')) ?>"><?= e(__('Service planning')) ?></a></div><h1><?= e(__('Songs')) ?></h1><p><?= e(__('Lyrics are not stored here (copyright). Add a link to your licensed chart or lyric source.')) ?></p></div></div>
<div class="split"><div class="card table-wrap"><table><thead><tr><th><?= e(__('Song')) ?></th><th>CCLI</th><th><?= e(__('Key')) ?></th><th><?= e(__('Used (12 months)')) ?></th><th><?= e(__('Last used')) ?></th></tr></thead><tbody>
<?php foreach ($songs as $x): ?><tr><td><a href="<?= e(url('/services/songs', ['edit' => $x['id']])) ?>"><?= e($x['title']) ?></a> <?= (int)$x['active'] ? '' : badge('inactive') ?><div class="small muted"><?= e($x['author']) ?></div></td><td class="small"><?= e($x['ccli_number']) ?></td><td><?= e($x['default_key']) ?></td><td><?= (int)$x['uses'] ?></td><td class="small"><?= e(fmt_date($x['last_used'])) ?></td></tr><?php endforeach; ?>
<?php if (!$songs): ?><tr><td colspan="5" class="empty"><?= e(__('No songs yet.')) ?></td></tr><?php endif; ?></tbody></table></div>
<form method="post" action="<?= e(url('/services/songs')) ?>" class="card form"><?= csrf_field() ?><h2 class="h3"><?= e($edit ? __('Edit song') : __('Add a song')) ?></h2><?php if ($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?>
<label><?= e(__('Title')) ?><input name="title" required value="<?= e($s['title'] ?? '') ?>"></label><label><?= e(__('Writers')) ?><input name="author" value="<?= e($s['author'] ?? '') ?>"></label>
<div class="grid-2"><label><?= e(__('CCLI song number')) ?><input name="ccli_number" value="<?= e($s['ccli_number'] ?? '') ?>" inputmode="numeric"></label><label><?= e(__('Default key')) ?><input name="default_key" value="<?= e($s['default_key'] ?? '') ?>"></label><label><?= e(__('Tempo')) ?><input name="tempo" value="<?= e($s['tempo'] ?? '') ?>"></label></div>
<label><?= e(__('Chart / lyrics link')) ?><input type="url" name="link_url" value="<?= e($s['link_url'] ?? '') ?>"></label><label><?= e(__('Notes')) ?><textarea name="notes" rows="2"><?= e($s['notes'] ?? '') ?></textarea></label>
<?php if ($edit): ?><label class="check"><input type="checkbox" name="active" value="1" <?= (int)$edit['active'] ? 'checked' : '' ?>> <?= e(__('Active')) ?></label><?php endif; ?>
<button class="btn btn-primary"><?= e(__('Save')) ?></button></form></div>
